#dar file main.py , agar yek file dari run mizni #az file import functionfrom calculator import jamfrom calculator import tafrigh as taffrom calculator import jam ,tafrigh, zarb #from calculator import * --> errro ha nadide gerefte #fastapi.get(/calculatuons)def main_calculator(numb1,numb2,operation):    if operation=='jam':        result = jam(numb1,numb2)        return {'success':True,'result':result}        elif operation=='tafrigh':        result = taf(numb1,numb2)        return {'success':True,'result':result}   